import { useEffect, useState } from "react";
import { Box, Button, Container, Stack, Typography } from "@mui/material";
import BlocksText from "../components/BlocksText";
import { mediaUrl } from "../services/api";
import type { CarouselSlide } from "../types/home";
import appStoreBadge from "../assets/icons/appstore-apple.png";
import playStoreBadge from "../assets/icons/g-play.png";

const BLUE = "#759ae1";
const APP_STORE_URL = "https://apps.apple.com/in/app/doctutorials-neet-pg-ss-fmge/id1475350376";
const PLAY_STORE_URL = "https://play.google.com/store/apps/details?id=in.dgist.doctutorials&hl=en_US";

type CarouselProps = {
  slides?: CarouselSlide[];
};

export default function Carousel({ slides = [] }: CarouselProps) {
  const [index, setIndex] = useState(0);

  useEffect(() => {
    if (slides.length < 2) return;
    const timer = window.setInterval(() => {
      setIndex((current) => (current + 1) % slides.length);
    }, 6000);
    return () => window.clearInterval(timer);
  }, [slides.length]);

  const slide = slides[index];
  if (!slide) return null;

  const background = mediaUrl(slide.banner);
  const image = mediaUrl(slide.image);

  return (
    <Box
      sx={{
        position: "relative",
        minHeight: { xs: 620, md: 560 },
        color: "#fff",
        overflow: "hidden",
        backgroundColor: "#7a9bd7",
        backgroundImage: background ? `url(${background})` : "none",
        backgroundSize: "cover",
        backgroundPosition: "center",
      }}
    >
      <Box sx={{ position: "absolute", inset: 0, backgroundColor: "rgba(122,155,215,0.45)" }} />
      <Container maxWidth="lg" sx={{ position: "relative", py: { xs: 5, md: 8 } }}>
        <Stack direction={{ xs: "column", md: "row" }} alignItems="center" spacing={{ xs: 3, md: 6 }}>
          <Box sx={{ flex: 1, width: "100%" }}>
            <Typography
              component="h1"
              sx={{
                fontSize: { xs: 28, md: 50 },
                fontWeight: 700,
                lineHeight: 1.15,
                mb: 1.5,
              }}
            >
              {slide.title}
            </Typography>
            <BlocksText
              content={slide.description}
              sx={{
                maxWidth: 560,
                mb: 3,
                "& p, & h3, & h4, & h5, & h6": {
                  fontSize: { xs: 16, md: 22 },
                  fontWeight: 400,
                  lineHeight: 1.5,
                  mb: 2,
                },
                "& ul": {
                  m: 0,
                  mb: 0,
                  pl: 2.5,
                },
                "& li": {
                  fontSize: { xs: 15, md: 18 },
                  lineHeight: 1.7,
                  mb: 0.25,
                },
              }}
            />
            <Button
              variant="contained"
              href="/subscribe"
              sx={{
                backgroundColor: "#fff",
                color: BLUE,
                borderRadius: "54px",
                px: 2.5,
                py: 1,
                fontSize: 16,
                fontWeight: 700,
                boxShadow: "none",
                "&:hover": { backgroundColor: "#f4f7ff", boxShadow: "none" },
              }}
            >
              Subscribe
            </Button>
            <Stack direction="row" alignItems="center" spacing={1.5} sx={{ mt: 2.5 }}>
              <Box
                component="a"
                href={APP_STORE_URL}
                target="_blank"
                rel="noopener noreferrer"
              >
                <Box
                  component="img"
                  src={appStoreBadge}
                  alt="Download on the App Store"
                  sx={{ height: { xs: 38, md: 44 }, display: "block" }}
                />
              </Box>
              <Box
                component="a"
                href={PLAY_STORE_URL}
                target="_blank"
                rel="noopener noreferrer"
              >
                <Box
                  component="img"
                  src={playStoreBadge}
                  alt="Get it on Google Play"
                  sx={{ height: { xs: 38, md: 44 }, display: "block" }}
                />
              </Box>
            </Stack>
            {image ? (
              <Box
                component="img"
                src={image}
                alt={slide.image?.alternativeText || slide.title}
                sx={{
                  display: { xs: "block", md: "none" },
                  width: "100%",
                  maxWidth: 420,
                  mt: 3,
                  mx: "auto",
                  aspectRatio: "4 / 3",
                  objectFit: "contain",
                }}
              />
            ) : null}
          </Box>
          {image ? (
            <Box
              sx={{
                flex: 1,
                width: "100%",
                display: { xs: "none", md: "block" },
                textAlign: "center",
              }}
            >
              <Box
                component="img"
                src={image}
                alt={slide.image?.alternativeText || slide.title}
                sx={{ width: "100%", maxWidth: 520, objectFit: "cover" }}
              />
            </Box>
          ) : null}
        </Stack>
      </Container>
      <Stack direction="row" justifyContent="center" spacing={1} sx={{ position: "relative", pb: 3 }}>
        {slides.map((item, dotIndex) => (
          <Box
            key={item.id || dotIndex}
            onClick={() => setIndex(dotIndex)}
            sx={{
              width: 10,
              height: 10,
              borderRadius: "50%",
              cursor: "pointer",
              backgroundColor: dotIndex === index ? "#fff" : "rgba(255,255,255,0.45)",
            }}
          />
        ))}
      </Stack>
    </Box>
  );
}
